function moment(){const [who,line]=current(),name=typeof who==='number'?getPerson(who===2&&state.onStage?3:who).name:'ECHO';modal(`<span class="eyebrow">A MOMENT WORTH KEEPING</span><h2 id="modal-title">Take the thought with you.</h2><div class="moment-card"><span class="eyebrow">ECHO / MINDS ON STAGE</span><blockquote>“${esc(line)}”</blockquote><p style="margin-bottom:0">${esc(name)} · ${esc(topics[state.topic].title)}</p></div><div class="modal-actions"><button class="secondary" id="copy-quote">Copy quote</button><button class="primary" id="save-quote">Save to my studio</button></div><p style="font-size:10px;margin-top:16px">Scripted AI-character dialogue · Saved locally in this browser</p>`);$('#copy-quote').onclick=async()=>{try{await navigator.clipboard.writeText(`“${line}” — ${name}\nECHO · Scripted demo\n${location.href}`);toast('Quote copied')}catch{toast('Select and copy the quote above')}};$('#save-quote').onclick=()=>{state.savedMoment={line,name};try{localStorage.setItem('echo-original-moment',JSON.stringify(state.savedMoment))}catch{}toast('Moment saved in My studio');$('#save-quote').textContent='Saved ✓';$('#save-quote').disabled=true}}
